result = Customers.WHERE(
    (join_date >= "2023-01-01") & (status == "Active")
).PARTITION(name="countries", by=country).CALCULATE(
    country=country,
    count=COUNT(Customers)
)

active_customers_since_2023 = Customers.WHERE(
    (join_date >= "2023-01-01") & (status == "Active")
)

result = active_customers_since_2023.PARTITION(
    name="country_groups", by=country
).CALCULATE(
    country=country,
    TAC=COUNT(Customers)
)

