code:
# Step 1: Filter for 'buy' transactions within the last 10 days and get the ticker symbol.
recent_buy_transactions = Transactions.WHERE(
    (transaction_type == 'buy') & (DATEDIFF("days", date_time, DATETIME('now')) <= 10)
).CALCULATE(
    ticker_symbol=ticker.symbol
)

# Step 2: Partition by ticker symbol, count the number of transactions, and select the top 2.
most_frequent_stocks = recent_buy_transactions.PARTITION(
    name="ticker_groups", by=(ticker_symbol)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    num_of_buy_transactions=COUNT(Transactions)
).TOP_K(2, by=num_of_buy_transactions.DESC())

