code:
sell_transactions_last_month = Transactions.WHERE(
    (transaction_type == 'sell') &
    (date_time >= DATETIME('now', '-1 month'))
)

transactions_with_symbol = sell_transactions_last_month.CALCULATE(
    ticker_symbol=ticker.symbol
)

result = transactions_with_symbol.PARTITION(
    name="ticker_group", by=(ticker_symbol)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    SPM=(
        (SUM(Transactions.amount) - (SUM(Transactions.tax) + SUM(Transactions.commission))) / SUM(Transactions.amount)
    ) * 100
)

