date_boundaries = Dealership.CALCULATE(
    current_month_start=DATETIME('now', 'start of month'),
    six_months_ago_start=DATETIME('now', 'start of month', '-6 months')
)
eligible_salespersons = date_boundaries.Salespersons.WHERE(
    (YEAR(hire_date) >= 2022) & (YEAR(hire_date) <= 2023)
)
calendar_months = date_boundaries.Sales.CALCULATE(
    sale_month=DATETIME(sale_date, 'start of month')
).PARTITION(name='months', by=sale_month).WHERE(
    (sale_month >= six_months_ago_start) & (sale_month < current_month_start)
)
result = calendar_months.CALCULATE(
    month=sale_month,
    sales_in_month=eligible_salespersons.sales_made.WHERE(
        DATETIME(sale_date, 'start of month') == sale_month
    )
).CALCULATE(
    month=month,
    PMSPS=COUNT(sales_in_month),
    PMSR=DEFAULT_TO(SUM(sales_in_month.sale_price), 0)
).ORDER_BY(month.ASC())

