code:
recent_transactions_received = Transactions.WHERE(
    (DATEDIFF("days", created_at, DATETIME('now')) <= 150) &
    (receiver_type == 1)
)

top_merchants_by_amount = Merchants.CALCULATE(
    merchant_name=name,
    total_number_of_transactions=COUNT(
        transactions_received.WHERE(
            (DATEDIFF("days", created_at, DATETIME('now')) <= 150) &
            (receiver_type == 1)
        )
    ),
    total_transaction_amount=SUM(
        transactions_received.WHERE(
            (DATEDIFF("days", created_at, DATETIME('now')) <= 150) &
            (receiver_type == 1)
        ).amount
    )
).WHERE(
    total_number_of_transactions > 0
).TOP_K(
    2,
    by=total_transaction_amount.DESC()
)

