# First, find the earliest snapshot date in 2023
earliest_date_2023 = UserSettingSnapshots.WHERE(
    YEAR(snapshot_date) == 2023
).CALCULATE(
    min_date=MIN(UserSettingSnapshots.snapshot_date)
).SINGULAR().min_date

# Then calculate the averages for snapshots on that date
result = UserSettingSnapshots.WHERE(
    snapshot_date == earliest_date_2023
).CALCULATE(
    avg_daily_limit=AVG(UserSettingSnapshots.tx_limit_daily),
    avg_monthly_limit=AVG(UserSettingSnapshots.tx_limit_monthly)
)

earliest_snapshots_2023 = UserSettingSnapshots.WHERE(
    YEAR(snapshot_date) == 2023
).WHERE(
    RANKING(by=snapshot_date.ASC(), allow_ties=True) == 1
)

average_limits = Ewallet.CALCULATE(
    avg_tx_limit_daily=AVG(earliest_snapshots_2023.tx_limit_daily),
    avg_tx_limit_monthly=AVG(earliest_snapshots_2023.tx_limit_monthly)
)

